import { useState, useEffect } from "react";
import { useAuth } from "@/hooks/useAuth";
import { AuthModal } from "./AuthModal";
import OrderFlowModal from "./OrderFlowModal";
import { PaymentModal } from "./PaymentModal";
import { useToast } from "@/hooks/use-toast";
import type { ServicePackage } from "@shared/schema";

interface AuthenticatedOrderFlowProps {
  isOpen: boolean;
  onClose: () => void;
  servicePackage: ServicePackage | null;
  initialStep?: number;
  savedProgress?: any;
}

interface OrderState {
  step: number;
  formData: any;
  selections: any;
  servicePackage: ServicePackage | null;
}

export function AuthenticatedOrderFlow({ 
  isOpen, 
  onClose, 
  servicePackage,
  initialStep = 1,
  savedProgress = null
}: AuthenticatedOrderFlowProps) {
  const { user, isLoading } = useAuth();
  const { toast } = useToast();

  const [authModalOpen, setAuthModalOpen] = useState(false);
  const [orderFlowOpen, setOrderFlowOpen] = useState(false);
  const [paymentModalOpen, setPaymentModalOpen] = useState(false);
  const [orderState, setOrderState] = useState<OrderState>({
    step: initialStep,
    formData: savedProgress?.formData || {},
    selections: savedProgress?.selections || {},
    servicePackage
  });

  // Check authentication when component opens
  useEffect(() => {
    if (isOpen && !isLoading) {
      if (!user) {
        // Save current state and show auth modal
        saveProgressToStorage();
        setAuthModalOpen(true);
      } else {
        // User is authenticated, proceed with order flow
        setOrderFlowOpen(true);
      }
    }
  }, [isOpen, user, isLoading]);

  // Save progress to localStorage for recovery after auth
  const saveProgressToStorage = () => {
    const progressData = {
      step: orderState.step,
      formData: orderState.formData,
      selections: orderState.selections,
      servicePackage: orderState.servicePackage,
      timestamp: Date.now()
    };
    localStorage.setItem('orderProgress', JSON.stringify(progressData));
  };

  // Load progress from localStorage after auth
  const loadProgressFromStorage = () => {
    try {
      const saved = localStorage.getItem('orderProgress');
      if (saved) {
        const progressData = JSON.parse(saved);
        // Only load if saved within last 30 minutes
        if (Date.now() - progressData.timestamp < 30 * 60 * 1000) {
          setOrderState(progressData);
          localStorage.removeItem('orderProgress'); // Clean up
          return progressData;
        }
      }
    } catch (error) {
      console.error('Failed to load progress:', error);
    }
    return null;
  };

  // Handle successful authentication
  const handleAuthSuccess = () => {
    setAuthModalOpen(false);

    // Load saved progress
    const savedProgress = loadProgressFromStorage();
    if (savedProgress) {
      setOrderState(savedProgress);
      toast({
        title: "Welcome back!",
        description: "Continuing where you left off...",
      });
    }

    // Open order flow
    setOrderFlowOpen(true);
  };

  // Handle order completion (ready for payment)
  const handleOrderComplete = (completedOrderData: any) => {
    setOrderFlowOpen(false);
    setOrderState(prev => ({
      ...prev,
      formData: completedOrderData
    }));
    setPaymentModalOpen(true);
  };

  // Handle payment completion
  const handlePaymentComplete = () => {
    setPaymentModalOpen(false);
    onClose();
    toast({
      title: "Order Submitted!",
      description: "Your project has been submitted successfully. We'll be in touch soon!",
    });
  };

  // Handle any modal close
  const handleClose = () => {
    if (orderFlowOpen) {
      // Save progress before closing
      saveProgressToStorage();
      toast({
        title: "Progress Saved",
        description: "Your progress has been saved. You can continue later!",
      });
    }

    setAuthModalOpen(false);
    setOrderFlowOpen(false);
    setPaymentModalOpen(false);
    onClose();
  };

  if (isLoading) {
    return null; // Or loading spinner
  }

  return (
    <>
      {/* Authentication Modal */}
      <AuthModal
        isOpen={authModalOpen}
        onClose={() => setAuthModalOpen(false)}
        onSuccess={handleAuthSuccess}
      />

      {/* Order Flow Modal */}
      <OrderFlowModal
        isOpen={orderFlowOpen}
        onClose={handleClose}
        servicePackage={orderState.servicePackage}
      />

      {/* Payment Modal */}
      <PaymentModal
        isOpen={paymentModalOpen}
        onClose={handleClose}
        orderData={orderState.formData}
        servicePackage={orderState.servicePackage}
        onComplete={handlePaymentComplete}
        user={user || null}
      />
    </>
  );
}

server/routes/admin-drizzle.ts.content:
import { Router } from 'express';
import { db } from '../db';
import { orders, payments, activities, users, servicePackages } from '../../shared/schema';
import { eq, desc, count, sum, and } from 'drizzle-orm';
import { requireAuth, requireAdmin, type AuthRequest } from '../middleware/auth';

const router = Router();

// Get admin dashboard data
router.get('/admin/dashboard', requireAuth, requireAdmin, async (req: AuthRequest, res) => {
  try {
    // Get order statistics
    const [totalOrdersResult] = await db.select({ count: count() }).from(orders);
    const [paidOrdersResult] = await db.select({ count: count() }).from(orders).where(eq(orders.status, 'PAID'));
    const [pendingOrdersResult] = await db.select({ count: count() }).from(orders).where(eq(orders.status, 'PENDING'));

    // Get revenue
    const [revenueResult] = await db.select({ 
      total: sum(orders.totalAmount) 
    }).from(orders).where(eq(orders.paymentStatus, 'paid'));

    // Get recent orders
    const recentOrders = await db.select({
      id: orders.id,
      totalAmount: orders.totalAmount,
      status: orders.status,
      createdAt: orders.createdAt,
      userEmail: users.email,
      serviceName: servicePackages.name,
    })
      .from(orders)
      .leftJoin(users, eq(orders.userId, users.id))
      .leftJoin(servicePackages, eq(orders.serviceId, servicePackages.id))
      .orderBy(desc(orders.createdAt))
      .limit(10);

    // Get recent activities
    const recentActivities = await db.select({
      id: activities.id,
      event: activities.event,
      entity: activities.entity,
      entityId: activities.entityId,
      metadata: activities.metadata,
      createdAt: activities.createdAt,
      userEmail: users.email,
    })
      .from(activities)
      .leftJoin(users, eq(activities.userId, users.id))
      .orderBy(desc(activities.createdAt))
      .limit(20);

    const dashboardData = {
      stats: {
        totalOrders: totalOrdersResult.count,
        paidOrders: paidOrdersResult.count,
        pendingOrders: pendingOrdersResult.count,
        totalRevenue: revenueResult.total || 0,
      },
      recentOrders,
      recentActivities,
    };

    res.json(dashboardData);
  } catch (error) {
    console.error('Dashboard error:', error);
    res.status(500).json({ error: 'Failed to load dashboard data' });
  }
});

// Update order status
router.patch('/admin/orders/:id/status', requireAuth, requireAdmin, async (req: AuthRequest, res) => {
  try {
    const { id } = req.params;
    const { status } = req.body;

    const [order] = await db.select().from(orders).where(eq(orders.id, parseInt(id))).limit(1);

    if (!order) {
      return res.status(404).json({ error: 'Order not found' });
    }

    const [updatedOrder] = await db.update(orders)
      .set({
        status,
        updatedAt: new Date(),
      })
      .where(eq(orders.id, parseInt(id)))
      .returning();

    // Log activity
    await db.insert(activities).values({
      userId: req.user!.id,
      event: 'ADMIN_ORDER_STATUS_UPDATE',
      entity: 'order',
      entityId: updatedOrder.id.toString(),
      metadata: {
        oldStatus: order.status,
        newStatus: status,
        adminId: req.user!.id
      }
    });

    res.json(updatedOrder);
  } catch (error) {
    console.error('Update order status error:', error);
    res.status(500).json({ error: 'Failed to update order status' });
  }
});

// Get all payments
router.get('/admin/payments', requireAuth, requireAdmin, async (req: AuthRequest, res) => {
  try {
    const allPayments = await db.select({
      id: payments.id,
      orderId: payments.orderId,
      amount: payments.amount,
      currency: payments.currency,
      paymentMethod: payments.paymentMethod,
      transactionId: payments.transactionId,
      status: payments.status,
      createdAt: payments.createdAt,
      updatedAt: payments.updatedAt,
    })
      .from(payments)
      .orderBy(desc(payments.createdAt));

    res.json(allPayments);
  } catch (error) {
    console.error('Get payments error:', error);
    res.status(500).json({ error: 'Failed to get payments' });
  }
});

// Get payment analytics
router.get('/admin/analytics/payments', requireAuth, requireAdmin, async (req: AuthRequest, res) => {
  try {
    const [totalPaymentsResult] = await db.select({ count: count() }).from(payments);
    const [successfulPaymentsResult] = await db.select({ count: count() })
      .from(payments).where(eq(payments.status, 'completed'));
    const [pendingPaymentsResult] = await db.select({ count: count() })
      .from(payments).where(eq(payments.status, 'pending'));
    const [failedPaymentsResult] = await db.select({ count: count() })
      .from(payments).where(eq(payments.status, 'failed'));

    const [totalRevenueResult] = await db.select({ 
      total: sum(payments.amount) 
    }).from(payments).where(eq(payments.status, 'completed'));

    const analytics = {
      totalPayments: totalPaymentsResult.count,
      successfulPayments: successfulPaymentsResult.count,
      pendingPayments: pendingPaymentsResult.count,
      failedPayments: failedPaymentsResult.count,
      totalRevenue: totalRevenueResult.total || 0,
      successRate: totalPaymentsResult.count > 0 
        ? (successfulPaymentsResult.count / totalPaymentsResult.count * 100).toFixed(2) 
        : '0',
    };

    res.json(analytics);
  } catch (error) {
    console.error('Payment analytics error:', error);
    res.status(500).json({ error: 'Failed to get payment analytics' });
  }
});

// Get payment details
router.get('/admin/payments/:id', requireAuth, requireAdmin, async (req: AuthRequest, res) => {
  try {
    const { id } = req.params;

    const [payment] = await db.select().from(payments).where(eq(payments.id, parseInt(id))).limit(1);

    if (!payment) {
      return res.status(404).json({ error: 'Payment not found' });
    }

    res.json(payment);
  } catch (error) {
    console.error('Get payment details error:', error);
    res.status(500).json({ error: 'Failed to get payment details' });
  }
});

// Get all orders for admin
router.get('/admin/orders', requireAuth, requireAdmin, async (req: AuthRequest, res) => {
  try {
    const allOrders = await db.select({
      id: orders.id,
      userId: orders.userId,
      serviceId: orders.serviceId,
      status: orders.status,
      totalAmount: orders.totalAmount,
      paymentStatus: orders.paymentStatus,
      orderData: orders.orderData,
      createdAt: orders.createdAt,
      updatedAt: orders.updatedAt,
      userEmail: users.email,
      serviceName: servicePackages.name,
    })
      .from(orders)
      .leftJoin(users, eq(orders.userId, users.id))
      .leftJoin(servicePackages, eq(orders.serviceId, servicePackages.id))
      .orderBy(desc(orders.createdAt));

    res.json(allOrders);
  } catch (error) {
    console.error('Get admin orders error:', error);
    res.status(500).json({ error: 'Failed to get orders' });
  }
});

// Get all activities for admin
router.get('/admin/activities', requireAuth, requireAdmin, async (req: AuthRequest, res) => {
  try {
    const allActivities = await db.select({
      id: activities.id,
      userId: activities.userId,
      event: activities.event,
      entity: activities.entity,
      entityId: activities.entityId,
      metadata: activities.metadata,
      createdAt: activities.createdAt,
      userEmail: users.email,
    })
      .from(activities)
      .leftJoin(users, eq(activities.userId, users.id))
      .orderBy(desc(activities.createdAt))
      .limit(100);

    res.json(allActivities);
  } catch (error) {
    console.error('Get activities error:', error);
    res.status(500).json({ error: 'Failed to get activities' });
  }
});

export default router;

