import { useState, useRef, useEffect } from "react";
import { Globe } from "lucide-react";
import { Button } from "@/components/ui/button";
import { useTranslation } from "react-i18next";
import { languages, getPathWithLanguage, type SupportedLanguage } from "@/i18n";

export default function LanguageSwitcher() {
  const { i18n } = useTranslation();
  const [isOpen, setIsOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    function handleClickOutside(e: MouseEvent) {
      if (
        dropdownRef.current &&
        !dropdownRef.current.contains(e.target as Node)
      ) {
        setIsOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const handleLanguageChange = (langCode: SupportedLanguage) => {
    setIsOpen(false);

    i18n.changeLanguage(langCode);

    const currentPath = window.location.pathname;
    const newPath = getPathWithLanguage(currentPath, langCode);

    document.documentElement.lang = langCode;
    document.documentElement.dir = langCode === "ar" ? "rtl" : "ltr";

    window.history.pushState({}, "", newPath);
    window.dispatchEvent(new PopStateEvent("popstate"));
  };

  const currentLang = i18n.language as SupportedLanguage;
  const currentLabel =
    languages.find((l) => l.code === currentLang)?.label || "English";

  return (
    <div
      ref={dropdownRef}
      className="relative"
      data-testid="language-switcher"
    >
      <Button
        variant="ghost"
        size="sm"
        onClick={() => setIsOpen(!isOpen)}
        className="flex items-center gap-1.5 text-gray-600 px-2"
        data-testid="button-language-toggle"
      >
        <Globe className="w-4 h-4" />
        <span className="text-xs font-medium">{currentLabel}</span>
      </Button>

      {isOpen && (
        <div
          className="absolute right-0 top-full mt-1 bg-white border border-gray-200 rounded-md shadow-lg z-[9999] min-w-[150px] py-1 max-h-[300px] overflow-y-auto"
          data-testid="language-dropdown"
        >
          {languages.map((lang) => (
            <button
              key={lang.code}
              onClick={() => handleLanguageChange(lang.code)}
              className={`w-full text-left px-3 py-1.5 text-sm transition-colors ${
                currentLang === lang.code
                  ? "bg-[#01A1C1]/10 text-[#01A1C1] font-medium"
                  : "text-gray-700 hover:bg-gray-50"
              }`}
              data-testid={`button-lang-${lang.code}`}
            >
              {lang.label}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

