import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import axios from 'axios';

interface User {
  id: string;
  email: string;
  firstName?: string;
  lastName?: string;
  role: string;
}

interface AuthContextType {
  user: User | null;
  token: string | null;
  login: (credentials: { email: string; password: string }, options?: { onSuccess?: () => void }) => Promise<void>;
  register: (userData: any, options?: { onSuccess?: () => void }) => Promise<void>;
  googleLogin: (credential: string, options?: { onSuccess?: () => void }) => Promise<void>;
  logout: () => void;
  updateUser: (userData: Partial<User>) => void;
  loading: boolean;
  isLoggingIn: boolean;
  isRegistering: boolean;
  isAuthenticated: boolean;
  isAdmin: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [token, setToken] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [isLoggingIn, setIsLoggingIn] = useState(false);
  const [isRegistering, setIsRegistering] = useState(false);

  useEffect(() => {
    // Check for existing token on app load
    const storedToken = localStorage.getItem('authToken');
    const storedUser = localStorage.getItem('user');

    if (storedToken && storedUser) {
      try {
        const userData = JSON.parse(storedUser);
        setToken(storedToken);
        setUser(userData);

        // Set default axios header
        axios.defaults.headers.common['Authorization'] = `Bearer ${storedToken}`;

        // Verify token is still valid
        verifyToken(storedToken);
      } catch (error) {
        console.error('Error parsing stored user data:', error);
        logout();
      }
    }

    setLoading(false);
  }, []);

  const verifyToken = async (token: string) => {
    try {
      const response = await axios.get('/api/auth/user', {
        headers: { Authorization: `Bearer ${token}` }
      });

      // Update user data if token is valid
      setUser(response.data);
      localStorage.setItem('user', JSON.stringify(response.data));
    } catch (error: any) {
      // Token is invalid or expired, silently logout
      if (error.response?.status === 401) {
        console.log('Token expired or invalid, logging out');
      } else {
        console.error('Token verification failed:', error);
      }
      logout();
    }
  };

  const login = async (credentials: { email: string; password: string }, options?: { onSuccess?: () => void }) => {
    setIsLoggingIn(true);
    try {
      const response = await axios.post('/api/auth/login', credentials);
      const { token: newToken, user: newUser } = response.data;

      setToken(newToken);
      setUser(newUser);
      localStorage.setItem('authToken', newToken);
      localStorage.setItem('user', JSON.stringify(newUser));
      axios.defaults.headers.common['Authorization'] = `Bearer ${newToken}`;

      options?.onSuccess?.();
    } catch (error) {
      console.error('Login failed:', error);
      throw error;
    } finally {
      setIsLoggingIn(false);
    }
  };

  const register = async (userData: any, options?: { onSuccess?: () => void }) => {
    setIsRegistering(true);
    try {
      const response = await axios.post('/api/auth/register', userData);
      const { token: newToken, user: newUser } = response.data;

      setToken(newToken);
      setUser(newUser);
      localStorage.setItem('authToken', newToken);
      localStorage.setItem('user', JSON.stringify(newUser));
      axios.defaults.headers.common['Authorization'] = `Bearer ${newToken}`;

      options?.onSuccess?.();
    } catch (error) {
      console.error('Registration failed:', error);
      throw error;
    } finally {
      setIsRegistering(false);
    }
  };

  const googleLogin = async (credential: string, options?: { onSuccess?: () => void }) => {
    setIsLoggingIn(true);
    try {
      const response = await axios.post('/api/auth/google', { credential });
      const { token: newToken, user: newUser } = response.data;

      setToken(newToken);
      setUser(newUser);
      localStorage.setItem('authToken', newToken);
      localStorage.setItem('user', JSON.stringify(newUser));
      axios.defaults.headers.common['Authorization'] = `Bearer ${newToken}`;

      options?.onSuccess?.();
    } catch (error) {
      console.error('Google login failed:', error);
      throw error;
    } finally {
      setIsLoggingIn(false);
    }
  };

  const updateUser = (userData: Partial<User>) => {
    if (user) {
      const updatedUser = { ...user, ...userData };
      setUser(updatedUser);
      localStorage.setItem('user', JSON.stringify(updatedUser));
    }
  };

  const logout = () => {
    setToken(null);
    setUser(null);
    localStorage.removeItem('authToken');
    localStorage.removeItem('user');
    delete axios.defaults.headers.common['Authorization'];
  };

  const value = {
    user,
    token,
    login,
    register,
    googleLogin,
    logout,
    updateUser,
    loading,
    isLoggingIn,
    isRegistering,
    isAuthenticated: !!user && !!token,
    isAdmin: user?.role === 'admin'
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

// Higher-order component for protecting routes
export function withAuth<P extends object>(Component: React.ComponentType<P>) {
  return function AuthenticatedComponent(props: P) {
    const { user, loading } = useAuth();

    if (loading) {
      return (
        <div className="flex items-center justify-center min-h-screen">
          <div>Loading...</div>
        </div>
      );
    }

    if (!user) {
      return <div>Please log in to access this page.</div>;
    }

    return <Component {...props} />;
  };
}

// Higher-order component for admin-only routes
export function withAdminAuth<P extends object>(Component: React.ComponentType<P>) {
  return function AdminAuthenticatedComponent(props: P) {
    const { user, loading } = useAuth();

    if (loading) {
      return (
        <div className="flex items-center justify-center min-h-screen">
          <div>Loading...</div>
        </div>
      );
    }

    if (!user) {
      return <div>Please log in to access this page.</div>;
    }

    if (user?.role !== 'admin') {
      return <div>Access denied. Admin privileges required.</div>;
    }

    return <Component {...props} />;
  };
}

