                </div>
                <p className="text-green-600 text-sm mb-4">
                  Your questionnaire has been completed. Our team will review your requirements and contact you with the next steps.
                </p>
                <Button 
                  onClick={onClose}
                  className="w-full bg-[#01A1C1] hover:bg-[#01A1C1]/90"
