import express, { type Express } from "express";
import fs from "fs";
import path from "path";
import { imageOptimizerMiddleware } from "./image-optimizer";

export function serveStaticFixed(app: Express) {
  const distPath = path.resolve(process.cwd(), "dist", "public");

  console.log("Current working directory:", process.cwd());
  console.log("Looking for static files at:", distPath);
  console.log("Directory exists:", fs.existsSync(distPath));

  if (fs.existsSync(distPath)) {
    console.log("Files in dist/public:", fs.readdirSync(distPath));
    const assetsPath = path.join(distPath, "assets");
    if (fs.existsSync(assetsPath)) {
      console.log("Files in assets:", fs.readdirSync(assetsPath).slice(0, 5));
    }
  }

  if (!fs.existsSync(distPath)) {
    throw new Error(
      `Could not find the build directory: ${distPath}, make sure to build the client first`,
    );
  }

  app.use(imageOptimizerMiddleware(distPath));

  app.use(express.static(distPath, {
    maxAge: "1y",
    immutable: true,
    etag: true,
    lastModified: true,
    setHeaders: (res, filePath) => {
      if (/\.(js|css)$/.test(filePath)) {
        res.setHeader("Cache-Control", "public, max-age=31536000, immutable");
      } else if (/\.(woff2?|ttf|eot|otf)$/.test(filePath)) {
        res.setHeader("Cache-Control", "public, max-age=31536000, immutable");
      } else if (/\.(png|jpg|jpeg|gif|svg|ico|webp|avif)$/.test(filePath)) {
        res.setHeader("Cache-Control", "public, max-age=31536000, immutable");
      } else if (/\.html$/.test(filePath)) {
        res.setHeader("Cache-Control", "no-cache");
      }
    },
  }));

  app.use((req, res, next) => {
    if (req.path.startsWith('/api/')) {
      return next();
    }

    res.set("Cache-Control", "no-cache");
    res.sendFile(path.resolve(distPath, "index.html"));
  });
}

