import { useState, useEffect, useRef, useCallback } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Separator } from "@/components/ui/separator";
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { Mail, Lock, User, Phone, Eye, EyeOff, CheckCircle } from "lucide-react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { useAuth } from "@/contexts/AuthContext";
import LoadingSpinner from "./LoadingSpinner";

declare global {
  interface Window {
    google?: {
      accounts: {
        id: {
          initialize: (config: any) => void;
          renderButton: (element: HTMLElement, config: any) => void;
          prompt: () => void;
        };
      };
    };
  }
}

// Form schemas
const loginSchema = z.object({
  email: z.string().email("Please enter a valid email"),
  password: z.string().min(6, "Password must be at least 6 characters"),
});

const registerSchema = z.object({
  email: z.string().email("Please enter a valid email"),
  password: z.string().min(6, "Password must be at least 6 characters"),
  firstName: z.string().min(1, "First name is required"),
  lastName: z.string().min(1, "Last name is required"),
  phone: z.string().min(9, "Please enter a valid phone number"),
});

type LoginForm = z.infer<typeof loginSchema>;
type RegisterForm = z.infer<typeof registerSchema>;

interface AuthModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccess?: () => void;
}

export function AuthModal({ isOpen, onClose, onSuccess }: AuthModalProps) {
  const [activeTab, setActiveTab] = useState("signin");
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [googleClientId, setGoogleClientId] = useState<string | null>(null);
  const [googleError, setGoogleError] = useState<string | null>(null);
  const googleSignInRef = useRef<HTMLDivElement>(null);
  const googleSignUpRef = useRef<HTMLDivElement>(null);

  const { login, register, googleLogin, isLoggingIn, isRegistering, user } = useAuth();

  useEffect(() => {
    fetch('/api/auth/google-client-id')
      .then(r => r.json())
      .then(data => { if (data.clientId) setGoogleClientId(data.clientId); })
      .catch(() => {});
  }, []);

  const initializeGoogleButton = useCallback((containerRef: React.RefObject<HTMLDivElement | null>) => {
    if (!googleClientId || !containerRef.current || !window.google?.accounts) return;

    containerRef.current.innerHTML = '';

    window.google.accounts.id.initialize({
      client_id: googleClientId,
      callback: async (response: any) => {
        try {
          setGoogleError(null);
          await googleLogin(response.credential, {
            onSuccess: () => {
              onClose();
              onSuccess?.();
            },
          });
        } catch (_e) {
          setGoogleError('Google sign-in failed. Please try again.');
        }
      },
    });

    window.google.accounts.id.renderButton(containerRef.current, {
      theme: 'outline',
      size: 'large',
      width: containerRef.current.offsetWidth,
      text: 'continue_with',
    });
  }, [googleClientId, googleLogin, onClose, onSuccess]);

  useEffect(() => {
    if (!googleClientId || !isOpen) return;

    const loadScript = () => {
      if (document.getElementById('google-gsi-script')) {
        setTimeout(() => {
          initializeGoogleButton(activeTab === 'signin' ? googleSignInRef : googleSignUpRef);
        }, 100);
        return;
      }

      const script = document.createElement('script');
      script.id = 'google-gsi-script';
      script.src = 'https://accounts.google.com/gsi/client';
      script.async = true;
      script.defer = true;
      script.onload = () => {
        setTimeout(() => {
          initializeGoogleButton(activeTab === 'signin' ? googleSignInRef : googleSignUpRef);
        }, 100);
      };
      document.head.appendChild(script);
    };

    loadScript();
  }, [googleClientId, isOpen, activeTab, initializeGoogleButton]);

  // Login form
  const loginForm = useForm<LoginForm>({
    resolver: zodResolver(loginSchema),
    defaultValues: {
      email: "",
      password: "",
    },
  });

  // Register form
  const registerForm = useForm<RegisterForm>({
    resolver: zodResolver(registerSchema),
    defaultValues: {
      email: "",
      password: "",
      firstName: "",
      lastName: "",
      phone: "",
    },
  });

  // Handle login
  const handleLogin = (data: LoginForm) => {
    login(data, {
      onSuccess: () => {
        onClose();
        loginForm.reset();
        onSuccess?.();
      },
    });
  };

  // Handle register
  const handleRegister = (data: RegisterForm) => {
    register(data, {
      onSuccess: () => {
        onClose();
        registerForm.reset();
        onSuccess?.();
      },
    });
  };

  // If user is already authenticated, don't show modal
  if (user) {
    return null;
  }

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-md max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="text-center text-2xl font-bold text-gray-900">
            Welcome to TechPartner Studio
          </DialogTitle>
        </DialogHeader>

        <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
          <TabsList className="grid w-full grid-cols-2 mb-6">
            <TabsTrigger value="signin" className="text-sm font-medium">Sign In</TabsTrigger>
            <TabsTrigger value="signup" className="text-sm font-medium">Sign Up</TabsTrigger>
          </TabsList>

          {/* Sign In Tab */}
          <TabsContent value="signin" className="space-y-6">
            <div className="space-y-4">
              {googleClientId && (
                <div className="space-y-3">
                  <div ref={googleSignInRef} className="w-full flex justify-center" data-testid="google-signin-button" />
                  {googleError && (
                    <p className="text-sm text-red-500 text-center">{googleError}</p>
                  )}
                </div>
              )}

              <div className="relative">
                <div className="absolute inset-0 flex items-center">
                  <Separator className="w-full" />
                </div>
                <div className="relative flex justify-center text-xs uppercase">
                  <span className="bg-white px-2 text-gray-500">Or continue with email</span>
                </div>
              </div>

              {/* Login Form */}
              <Form {...loginForm}>
                <form onSubmit={loginForm.handleSubmit(handleLogin)} className="space-y-4">
                  <FormField
                    control={loginForm.control}
                    name="email"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel className="text-gray-700 font-medium">Email</FormLabel>
                        <FormControl>
                          <div className="relative">
                            <Mail className="absolute left-3 top-3 h-5 w-5 text-gray-400" />
                            <Input
                              {...field}
                              type="email"
                              placeholder="Enter your email"
                              className="pl-10 h-12 border-gray-300 focus:border-[#01A1C1] focus:ring-[#01A1C1]"
                            />
                          </div>
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={loginForm.control}
                    name="password"
                    render={({ field }) => (
                      <FormItem>
