import React, { useState } from 'react';
import { X, Upload, ChevronLeft, ChevronRight, ArrowRight } from 'lucide-react';
import type { ServicePackage } from '@shared/schema';

interface GeneralProjectQuestionnaireModalProps {
  isOpen: boolean;
  onClose: () => void;
