import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { useAuth } from "@/contexts/AuthContext";
import LoadingSpinner from "./LoadingSpinner";

declare global {
  interface Window {
    google?: {
      accounts: {
        id: {
          initialize: (config: any) => void;
          renderButton: (element: HTMLElement, config: any) => void;
          prompt: () => void;
        };
      };
    };
  }
}

// Form schemas
const loginSchema = z.object({
  email: z.string().email("Please enter a valid email"),
  password: z.string().min(6, "Password must be at least 6 characters"),
});

const registerSchema = z.object({
  email: z.string().email("Please enter a valid email"),
  password: z.string().min(6, "Password must be at least 6 characters"),
  firstName: z.string().min(1, "First name is required"),
  lastName: z.string().min(1, "Last name is required"),
  phone: z.string().min(9, "Please enter a valid phone number"),
});

type LoginForm = z.infer<typeof loginSchema>;
type RegisterForm = z.infer<typeof registerSchema>;

interface AuthModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccess?: () => void;
}

export function AuthModal({ isOpen, onClose, onSuccess }: AuthModalProps) {
  const [activeTab, setActiveTab] = useState("signin");
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [googleClientId, setGoogleClientId] = useState<string | null>(null);
  const [googleError, setGoogleError] = useState<string | null>(null);
  const googleSignInRef = useRef<HTMLDivElement>(null);
  const googleSignUpRef = useRef<HTMLDivElement>(null);

  const { login, register, googleLogin, isLoggingIn, isRegistering, user } = useAuth();

  useEffect(() => {
    fetch('/api/auth/google-client-id')
      .then(r => r.json())
      .then(data => { if (data.clientId) setGoogleClientId(data.clientId); })
      .catch(() => {});
  }, []);

  const initializeGoogleButton = useCallback((containerRef: React.RefObject<HTMLDivElement | null>) => {
    if (!googleClientId || !containerRef.current || !window.google?.accounts) return;

    containerRef.current.innerHTML = '';

    window.google.accounts.id.initialize({
      client_id: googleClientId,
      callback: async (response: any) => {
        try {
          setGoogleError(null);
          await googleLogin(response.credential, {
            onSuccess: () => {
              onClose();
              onSuccess?.();
            },
          });
        } catch (_e) {
          setGoogleError('Google sign-in failed. Please try again.');
        }
      },
    });

    window.google.accounts.id.renderButton(containerRef.current, {
      theme: 'outline',
      size: 'large',
      width: containerRef.current.offsetWidth,
      text: 'continue_with',
    });
  }, [googleClientId, googleLogin, onClose, onSuccess]);

  useEffect(() => {
    if (!googleClientId || !isOpen) return;

    const loadScript = () => {
      if (document.getElementById('google-gsi-script')) {
        setTimeout(() => {
          initializeGoogleButton(activeTab === 'signin' ? googleSignInRef : googleSignUpRef);
        }, 100);
        return;
      }

      const script = document.createElement('script');
      script.id = 'google-gsi-script';
      script.src = 'https://accounts.google.com/gsi/client';
      script.async = true;
      script.defer = true;
      script.onload = () => {
        setTimeout(() => {
          initializeGoogleButton(activeTab === 'signin' ? googleSignInRef : googleSignUpRef);
        }, 100);
      };
      document.head.appendChild(script);
    };

    loadScript();
  }, [googleClientId, isOpen, activeTab, initializeGoogleButton]);

  // Login form
  const loginForm = useForm<LoginForm>({
    resolver: zodResolver(loginSchema),
    defaultValues: {
      email: "",
      password: "",
    },
  });

  // Register form
  const registerForm = useForm<RegisterForm>({
    resolver: zodResolver(registerSchema),
    defaultValues: {
      email: "",
      password: "",
      firstName: "",
      lastName: "",
      phone: "",
    },
  });

  // Handle login
  const handleLogin = (data: LoginForm) => {
    login(data, {
      onSuccess: () => {
        onClose();
        loginForm.reset();
        onSuccess?.();
      },
    });
  };

  // Handle register
  const handleRegister = (data: RegisterForm) => {
    register(data, {
      onSuccess: () => {
        onClose();
        registerForm.reset();
        onSuccess?.();
      },
    });
  };

  // If user is already authenticated, don't show modal
  if (user) {
    return null;
  }

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-md max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="text-center text-2xl font-bold text-gray-900">
            Welcome to TechPartner Studio
          </DialogTitle>
        </DialogHeader>

        <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
          <TabsList className="grid w-full grid-cols-2 mb-6">
            <TabsTrigger value="signin" className="text-sm font-medium">Sign In</TabsTrigger>
            <TabsTrigger value="signup" className="text-sm font-medium">Sign Up</TabsTrigger>
          </TabsList>

          {/* Sign In Tab */}
          <TabsContent value="signin" className="space-y-6">
            <div className="space-y-4">
              {googleClientId && (
                <div className="space-y-3">
                  <div ref={googleSignInRef} className="w-full flex justify-center" data-testid="google-signin-button" />
                  {googleError && (
                    <p className="text-sm text-red-500 text-center">{googleError}</p>
                  )}
                </div>
              )}

              <div className="relative">
                <div className="absolute inset-0 flex items-center">
                  <Separator className="w-full" />
                </div>
                <div className="relative flex justify-center text-xs uppercase">
                  <span className="bg-white px-2 text-gray-500">Or continue with email</span>
                </div>
              </div>

              {/* Login Form */}
              <Form {...loginForm}>
                <form onSubmit={loginForm.handleSubmit(handleLogin)} className="space-y-4">
                  <FormField
                    control={loginForm.control}
                    name="email"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel className="text-gray-700 font-medium">Email</FormLabel>
                        <FormControl>
                          <div className="relative">
                            <Mail className="absolute left-3 top-3 h-5 w-5 text-gray-400" />
                            <Input
                              {...field}
                              type="email"
                              placeholder="Enter your email"
                              className="pl-10 h-12 border-gray-300 focus:border-[#01A1C1] focus:ring-[#01A1C1]"
                            />
                          </div>
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={loginForm.control}
                    name="password"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel className="text-gray-700 font-medium">Password</FormLabel>
                        <FormControl>
                          <div className="relative">
                            <Lock className="absolute left-3 top-3 h-5 w-5 text-gray-400" />
                            <Input
                              {...field}
                              type={showPassword ? "text" : "password"}
                              placeholder="Enter your password"
                              className="pl-10 pr-10 h-12 border-gray-300 focus:border-[#01A1C1] focus:ring-[#01A1C1]"
                            />
                            <button
                              type="button"
                              onClick={() => setShowPassword(!showPassword)}
                              className="absolute right-3 top-3 text-gray-400 hover:text-gray-600"
                            >
                              {showPassword ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}
                            </button>
                          </div>
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <div className="flex items-center justify-between">
                    <div className="flex items-center">
                      <input
                        id="remember-me"
                        name="remember-me"
                        type="checkbox"
                        className="h-4 w-4 text-[#01A1C1] focus:ring-[#01A1C1] border-gray-300 rounded"
                      />
                      <label htmlFor="remember-me" className="ml-2 block text-sm text-gray-700">
                        Remember me
                      </label>
                    </div>
                    <button type="button" className="text-sm text-[#01A1C1] hover:text-[#0891B2]">
                      Forgot password?
                    </button>
                  </div>

                  <Button 
                    type="submit" 
                    className="w-full h-12 bg-[#01A1C1] hover:bg-[#0891B2] text-white font-medium"
                    disabled={isLoggingIn}
                  >
                    {isLoggingIn ? <LoadingSpinner size="sm" /> : "Sign In"}
                  </Button>
                </form>
              </Form>
            </div>
          </TabsContent>

          {/* Sign Up Tab */}
          <TabsContent value="signup" className="space-y-6">
            <div className="space-y-4">
              {googleClientId && (
                <div className="space-y-3">
                  <div ref={googleSignUpRef} className="w-full flex justify-center" data-testid="google-signup-button" />
                  {googleError && (
                    <p className="text-sm text-red-500 text-center">{googleError}</p>
                  )}
                </div>
              )}

              <div className="relative">
                <div className="absolute inset-0 flex items-center">
                  <Separator className="w-full" />
                </div>
                <div className="relative flex justify-center text-xs uppercase">
                  <span className="bg-white px-2 text-gray-500">Or register with email</span>
                </div>
              </div>

              {/* Register Form */}
              <Form {...registerForm}>
                <form onSubmit={registerForm.handleSubmit(handleRegister)} className="space-y-4">
                  <div className="grid grid-cols-2 gap-4">
                    <FormField
                      control={registerForm.control}
                      name="firstName"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel className="text-gray-700 font-medium">First Name</FormLabel>
                          <FormControl>
                            <div className="relative">
                              <User className="absolute left-3 top-3 h-5 w-5 text-gray-400" />
                              <Input
                                {...field}
                                placeholder="First name"
                                className="pl-10 h-12 border-gray-300 focus:border-[#01A1C1] focus:ring-[#01A1C1]"
                              />
                            </div>
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={registerForm.control}
                      name="lastName"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel className="text-gray-700 font-medium">Last Name</FormLabel>
                          <FormControl>
                            <div className="relative">
                              <User className="absolute left-3 top-3 h-5 w-5 text-gray-400" />
                              <Input
                                {...field}
                                placeholder="Last name"
                                className="pl-10 h-12 border-gray-300 focus:border-[#01A1C1] focus:ring-[#01A1C1]"
                              />
                            </div>
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </div>

                  <FormField
                    control={registerForm.control}
                    name="email"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel className="text-gray-700 font-medium">Email</FormLabel>
                        <FormControl>
                          <div className="relative">
                            <Mail className="absolute left-3 top-3 h-5 w-5 text-gray-400" />
                            <Input
                              {...field}
                              type="email"
                              placeholder="Enter your email"
                              className="pl-10 h-12 border-gray-300 focus:border-[#01A1C1] focus:ring-[#01A1C1]"
                            />
                          </div>
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={registerForm.control}
                    name="phone"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel className="text-gray-700 font-medium">Phone</FormLabel>
                        <FormControl>
                          <div className="relative">
                            <Phone className="absolute left-3 top-3 h-5 w-5 text-gray-400" />
                            <Input
                              {...field}
                              placeholder="+966 56 176 1867"
                              className="pl-10 h-12 border-gray-300 focus:border-[#01A1C1] focus:ring-[#01A1C1]"
                            />
                          </div>
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={registerForm.control}
                    name="password"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel className="text-gray-700 font-medium">Password</FormLabel>
                        <FormControl>
                          <div className="relative">
                            <Lock className="absolute left-3 top-3 h-5 w-5 text-gray-400" />
                            <Input
                              {...field}
                              type={showConfirmPassword ? "text" : "password"}
                              placeholder="Create a strong password"
                              className="pl-10 pr-10 h-12 border-gray-300 focus:border-[#01A1C1] focus:ring-[#01A1C1]"
                            />
                            <button
                              type="button"
                              onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                              className="absolute right-3 top-3 text-gray-400 hover:text-gray-600"
                            >
                              {showConfirmPassword ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}
                            </button>
                          </div>
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <div className="flex items-center">
                    <input
                      id="agree-terms"
                      name="agree-terms"
                      type="checkbox"
                      required
                      className="h-4 w-4 text-[#01A1C1] focus:ring-[#01A1C1] border-gray-300 rounded"
                    />
                    <label htmlFor="agree-terms" className="ml-2 block text-sm text-gray-700">
                      I agree to the{" "}
                      <span className="text-[#01A1C1] hover:text-[#0891B2] cursor-pointer">Terms of Service</span>
                      {" "}and{" "}
                      <span className="text-[#01A1C1] hover:text-[#0891B2] cursor-pointer">Privacy Policy</span>
                    </label>
                  </div>

                  <Button 
                    type="submit" 
                    className="w-full h-12 bg-[#01A1C1] hover:bg-[#0891B2] text-white font-medium"
                    disabled={isRegistering}
                  >
                    {isRegistering ? <LoadingSpinner size="sm" /> : "Create Account"}
                  </Button>
                </form>
              </Form>
            </div>
          </TabsContent>
        </Tabs>

        {/* Features */}
        <div className="mt-6 p-4 bg-gray-50 rounded-lg">
          <h4 className="text-sm font-medium text-gray-900 mb-3">Why choose TechPartner Studio?</h4>
          <div className="space-y-2">
            <div className="flex items-center text-sm text-gray-600">
              <CheckCircle className="w-4 h-4 text-green-500 mr-2 flex-shrink-0" />
              Expert designers and developers
            </div>
            <div className="flex items-center text-sm text-gray-600">
              <CheckCircle className="w-4 h-4 text-green-500 mr-2 flex-shrink-0" />
              Fast turnaround with unlimited revisions
            </div>
            <div className="flex items-center text-sm text-gray-600">
              <CheckCircle className="w-4 h-4 text-green-500 mr-2 flex-shrink-0" />
              24/7 support and project management
            </div>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

