import { Globe } from "lucide-react";
import { Button } from "@/components/ui/button";

const languages = [
  { code: "en", label: "English" },
  { code: "ar", label: "العربية" },
];

function getCurrentLangFromPath(): string {
  return /^\/ar(\/|$)/.test(window.location.pathname) ? "ar" : "en";
}

function buildLangPath(targetLang: string): string {
  const path = window.location.pathname;
  const stripped = path.replace(/^\/ar(\/|$)/, "$1") || "/";
  if (targetLang === "ar") {
    return `/ar${stripped === "/" ? "" : stripped}`;
  }
  return stripped;
}

export default function LanguageSwitcher() {
  const currentLang = getCurrentLangFromPath();

  const switchLanguage = (langCode: string) => {
    if (langCode === currentLang) return;
    const newPath = buildLangPath(langCode);
    window.location.href = newPath;
  };

  return (
    <div className="relative notranslate" data-testid="language-switcher">
      {languages.map((lang) => (
        lang.code !== currentLang ? (
          <Button
            key={lang.code}
            variant="ghost"
            size="sm"
            onClick={() => switchLanguage(lang.code)}
            className="flex items-center gap-1.5 text-gray-600 px-2"
            data-testid={`button-lang-${lang.code}`}
          >
            <Globe className="w-4 h-4" />
            <span className="text-xs font-medium">{lang.label}</span>
          </Button>
        ) : null
      ))}
    </div>
  );
}

