import { Switch, Route } from "wouter";
import { queryClient } from "./lib/queryClient";
import { QueryClientProvider } from "@tanstack/react-query";
import { Toaster } from "@/components/ui/toaster";
import { TooltipProvider } from "@/components/ui/tooltip";
import { AuthProvider } from "@/contexts/AuthContext";
import { useTranslation } from "react-i18next";
import { useEffect } from "react";
import Home from "@/pages/home";
import CategoryPage from "@/pages/category";
import LogoIdentityPage from "@/pages/logo-identity";
import WebAppDesignPage from "@/pages/web-app-design";
import Dashboard from "@/pages/dashboard";
import Profile from "@/pages/Profile";
import Orders from "@/pages/Orders";
import AboutPage from "@/pages/about";
import ContactPage from "@/pages/contact";
import PortfolioPage from "@/pages/portfolio";
import BlogPage from "@/pages/blog";
import AdminPage from "@/pages/admin";
import AIDevelopmentPage from "@/pages/ai-development";
import PaymentSuccess from "@/pages/payment-success";
import NotFound from "@/pages/not-found";
import Header from "@/components/Header";
import Footer from "@/components/Footer";

const routeDefs = [
  { path: "/", component: Home },
  { path: "/dashboard", component: Dashboard },
  { path: "/profile", component: Profile },
  { path: "/orders", component: Orders },
  { path: "/categories", component: CategoryPage },
  { path: "/categories/logo-and-identity", component: LogoIdentityPage },
  { path: "/categories/web-and-app-design", component: WebAppDesignPage },
  { path: "/categories/web-development", component: WebAppDesignPage },
  { path: "/categories/business-advertising", component: CategoryPage },
  { path: "/categories/art-illustration", component: CategoryPage },
  { path: "/categories/packaging-label", component: CategoryPage },
  { path: "/categories/social-media", component: CategoryPage },
  { path: "/categories/print-design", component: CategoryPage },
  { path: "/logo-identity", component: LogoIdentityPage },
  { path: "/web-app-design", component: WebAppDesignPage },
  { path: "/about", component: AboutPage },
  { path: "/contact", component: ContactPage },
  { path: "/portfolio", component: PortfolioPage },
  { path: "/blog", component: BlogPage },
  { path: "/ai-development", component: AIDevelopmentPage },
  { path: "/admin", component: AdminPage },
  { path: "/payment/success", component: PaymentSuccess },
  { path: "/category/:slug", component: CategoryPage },
];

function AppRouter() {
  return (
    <Switch>
      {routeDefs.map((r) => (
        <Route key={r.path} path={r.path} component={r.component} />
      ))}
      {routeDefs.map((r) => (
        <Route
          key={`ar-${r.path}`}
          path={`/ar${r.path === "/" ? "" : r.path}`}
          component={r.component}
        />
      ))}
      <Route component={NotFound} />
    </Switch>
  );
}

function LanguageSync() {
  const { i18n } = useTranslation();

  useEffect(() => {
    const syncLang = () => {
      const isArabic = /^\/ar(\/|$)/.test(window.location.pathname);
      const urlLang = isArabic ? "ar" : "en";
      if (urlLang !== i18n.language) {
        i18n.changeLanguage(urlLang);
      }
      document.documentElement.lang = urlLang;
      document.documentElement.dir = isArabic ? "rtl" : "ltr";
    };
    syncLang();
    const events = ["popstate", "pushState", "replaceState", "hashchange"];
    for (const event of events) {
      addEventListener(event, syncLang);
    }
    return () => {
      for (const event of events) {
        removeEventListener(event, syncLang);
      }
    };
  }, [i18n]);

  return null;
}

function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <AuthProvider>
        <TooltipProvider>
          <LanguageSync />
          <div className="min-h-screen flex flex-col">
            <Header />
            <main className="flex-1">
              <AppRouter />
            </main>
            <Footer />
          </div>
          <Toaster />
        </TooltipProvider>
      </AuthProvider>
    </QueryClientProvider>
  );
}

export default App;

