function DebugRoute() {
  const [path, setPath] = useState(window.location.pathname);
  useEffect(() => {
    const fn = () => setPath(window.location.pathname);
    window.addEventListener("popstate", fn);
    return () => window.removeEventListener("popstate", fn);
  }, []);
  return <div style={{position:'fixed',top:0,left:'50%',zIndex:99999,background:'red',color:'white',padding:'10px',fontSize:'16px'}}>PATH: {path}</div>;
}

function AppRoutes() {
  return (
    <Switch>
      <Route path="/ar">{() => <div data-testid="text-ar-test" style={{padding: '100px', fontSize: '30px'}}>AR ROOT WORKS</div>}</Route>
      <Route path="/ar/about" component={AboutPage} />
      {routes.map((r) => (
        <Route key={r.path} path={r.path} component={r.component} />
      ))}
      {routes.map((r) => (
        <Route key={`ar-${r.path}`} path={`/ar${r.path === "/" ? "" : r.path}`} component={r.component} />
      ))}
      <Route component={NotFound} />
    </Switch>
  );
}

function LanguageSync() {
  const { i18n } = useTranslation();

  useEffect(() => {
    const syncLang = () => {
      const path = window.location.pathname;
      const urlLang = /^\/ar(\/|$)/.test(path) ? "ar" : "en";
      if (urlLang !== i18n.language) {
        i18n.changeLanguage(urlLang);
      }
    };
    syncLang();
    const events = ["popstate", "pushState", "replaceState", "hashchange"];
    for (const event of events) {
      addEventListener(event, syncLang);
    }
    return () => {
      for (const event of events) {
        removeEventListener(event, syncLang);
      }
    };
  }, [i18n]);

  useEffect(() => {
    document.documentElement.lang = i18n.language;
    document.documentElement.dir = isRTL(i18n.language) ? "rtl" : "ltr";
  }, [i18n.language]);

  return null;
}

function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <AuthProvider>
        <TooltipProvider>
          <LanguageSync />
          <DebugRoute />
          <div className="min-h-screen flex flex-col">
            <Header />
            <main className="flex-1">
              <AppRoutes />
            </main>
            <Footer />
          </div>
          <Toaster />
        </TooltipProvider>
      </AuthProvider>
    </QueryClientProvider>
  );
}

export default App;

