import i18n from "i18next";
import { initReactI18next } from "react-i18next";
import en from "./locales/en.json";
import ar from "./locales/ar.json";

const supportedLanguages = ["en", "ar"] as const;
export type SupportedLanguage = (typeof supportedLanguages)[number];

export const languages: { code: SupportedLanguage; label: string; dir: "ltr" | "rtl" }[] = [
  { code: "en", label: "English", dir: "ltr" },
  { code: "ar", label: "العربية", dir: "rtl" },
];

function getLanguageFromPath(): SupportedLanguage {
  const path = window.location.pathname;
  const match = path.match(/^\/([a-z]{2})(\/|$)/);
  if (match && supportedLanguages.includes(match[1] as SupportedLanguage)) {
    return match[1] as SupportedLanguage;
  }
  return "en";
}

i18n.use(initReactI18next).init({
  resources: {
    en: { translation: en },
    ar: { translation: ar },
  },
  lng: getLanguageFromPath(),
  fallbackLng: "en",
  interpolation: {
    escapeValue: false,
  },
  react: {
    useSuspense: false,
  },
});

export function isRTL(lang: string): boolean {
  return lang === "ar";
}

export function getPathWithLanguage(path: string, lang: SupportedLanguage): string {
  const cleanPath = path.replace(/^\/[a-z]{2}(\/|$)/, "$1") || "/";
  if (lang === "en") {
    return cleanPath;
  }
  return `/${lang}${cleanPath === "/" ? "" : cleanPath}`;
}

export function getPathWithoutLanguage(path: string): string {
  return path.replace(/^\/[a-z]{2}(\/|$)/, "$1") || "/";
}

export default i18n;

