import { Link } from "wouter";
import { localizedPath } from "../lib/language";

interface LocalizedLinkProps {
  to: string;
  children: React.ReactNode;
  className?: string;
  onClick?: () => void;
}

export default function LocalizedLink({ to, children, className, onClick, ...rest }: LocalizedLinkProps & Record<string, any>) {
  return (
    <Link to={localizedPath(to)} className={className} onClick={onClick} {...rest}>
      {children}
    </Link>
  );
}

