export function getCurrentLang(): string {
  return /^\/ar(\/|$)/.test(window.location.pathname) ? "ar" : "en";
}

export function localizedPath(path: string): string {
  if (!path || path.startsWith("http") || path.startsWith("#") || path.startsWith("/ar")) {
    return path;
  }
  const lang = getCurrentLang();
  if (lang === "ar") {
    return `/ar${path === "/" ? "" : path}`;
  }
  return path;
}

